) as c(id, n)
join public.cases cc on cc.id = c.id
cross join lateral (
  select p.id as voter from public.profiles p
  where p.id != cc.author_id
  order by random() limit c.n
) v;
select setval(pg_get_serial_sequence('public.cases','id'), (select max(id) from public.cases));
select setval(pg_get_serial_sequence('public.votes','id'), (select max(id) from public.votes));
